<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_customizer_social( $wp_customize ) { $wp_customize->add_section( 'sd_social_features', array( 'title' => __( 'Social Discovery Features', 'social-discovery' ), 'panel' => 'sd_settings' ) ); $settings = array( 'sd_social_feed_layout' => array( 'default', array( 'default' => 'Default', 'compact' => 'Compact' ) ), 'sd_social_card_style' => array( 'default', array( 'default' => 'Default', 'bordered' => 'Bordered' ) ), 'sd_social_member_layout' => array( 'grid', array( 'grid' => 'Grid', 'list' => 'List', 'compact' => 'Compact' ) ), 'sd_social_default_sort' => array( 'active', array( 'active' => 'Recently active', 'newest' => 'Newest', 'alphabetical' => 'Alphabetical' ) ) ); foreach ( $settings as $id => $config ) { $wp_customize->add_setting( $id, array( 'default' => $config[0], 'sanitize_callback' => 'sd_sanitize_select' ) ); $wp_customize->add_control( $id, array( 'label' => ucwords( str_replace( '_', ' ', str_replace( 'sd_social_', '', $id ) ) ), 'section' => 'sd_social_features', 'type' => 'select', 'choices' => $config[1] ) ); } foreach ( array( 'sd_social_sidebar' => 'Show feed sidebars' ) as $id => $label ) { $wp_customize->add_setting( $id, array( 'default' => true, 'sanitize_callback' => 'wp_validate_boolean' ) ); $wp_customize->add_control( $id, array( 'label' => $label, 'section' => 'sd_social_features', 'type' => 'checkbox' ) ); } foreach ( array( 'sd_social_directory_columns' => array( 'Directory columns', 1, 4 ), 'sd_social_suggested_members' => array( 'Suggested members', 1, 12 ), 'sd_social_suggested_communities' => array( 'Suggested communities', 1, 12 ) ) as $id => $config ) { $wp_customize->add_setting( $id, array( 'default' => $config[1], 'sanitize_callback' => 'sd_sanitize_positive_int' ) ); $wp_customize->add_control( $id, array( 'label' => $config[0], 'section' => 'sd_social_features', 'type' => 'number', 'input_attrs' => array( 'min' => $config[1], 'max' => $config[2] ) ) ); } }
add_action( 'customize_register', 'sd_customizer_social' );
